import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.DoRPXVp_.js";const m=JSON.parse('{"title":"AI Chat UI 优化设计","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-11-ai-chat-ui-improvement-design.md","filePath":"superpowers/specs/2026-05-11-ai-chat-ui-improvement-design.md"}'),i={name:"superpowers/specs/2026-05-11-ai-chat-ui-improvement-design.md"};function d(l,e,s,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-chat-ui-优化设计" tabindex="-1">AI Chat UI 优化设计 <a class="header-anchor" href="#ai-chat-ui-优化设计" aria-label="Permalink to &quot;AI Chat UI 优化设计&quot;">​</a></h1><p><strong>日期：</strong> 2026-05-11 <strong>范围：</strong> <code>fronted/src/components/ai/</code> + <code>fronted/src/pages/ai/index.vue</code> + <code>fronted/src/stores/useAiStore.ts</code></p><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>当前 AI chat 页面存在以下问题：</p><ul><li>消息布局不一致（用户消息和 AI 消息的宽度参照系不同）</li><li>Markdown 渲染为手写正则，有边界 bug，代码块无高亮无复制按钮</li><li>对话侧边栏标题永远是&quot;新对话&quot;</li><li>缺少基础交互细节：时间戳、复制按钮、顶部标题栏</li><li>空状态欢迎页推荐问题布局过于简单</li></ul><hr><h2 id="设计决策" tabindex="-1">设计决策 <a class="header-anchor" href="#设计决策" aria-label="Permalink to &quot;设计决策&quot;">​</a></h2><h3 id="_1-消息布局-用户气泡-ai-正文" tabindex="-1">1. 消息布局：用户气泡 + AI 正文 <a class="header-anchor" href="#_1-消息布局-用户气泡-ai-正文" aria-label="Permalink to &quot;1. 消息布局：用户气泡 + AI 正文&quot;">​</a></h3><p>采用 ChatGPT 风格：</p><ul><li>用户消息：右侧气泡，<code>bg-primary</code> 颜色，最宽 75%，右下角圆角收窄</li><li>AI 消息：左侧无背景，直接展示为正文，在 <code>max-w-3xl</code> 容器内，顶部显示&quot;Lattice AI · HH:mm&quot;</li><li>所有消息统一在 <code>max-w-3xl mx-auto</code> 的限宽容器中，消除两种消息宽度参照系不一致的问题</li><li>顶部新增标题栏，显示当前对话标题 + 模型名</li></ul><h3 id="_2-markdown-渲染-marked-highlight-js" tabindex="-1">2. Markdown 渲染：marked + highlight.js <a class="header-anchor" href="#_2-markdown-渲染-marked-highlight-js" aria-label="Permalink to &quot;2. Markdown 渲染：marked + highlight.js&quot;">​</a></h3><ul><li>移除 <code>MessageBubble.vue</code> 中手写的 <code>renderMarkdown</code> 正则函数</li><li>引入 <code>marked</code>（Markdown 解析）+ <code>highlight.js</code>（语法高亮）</li><li>代码块渲染：顶部工具栏显示语言标识 + 复制按钮，暗色主题</li><li><code>marked</code> 配置使用 <code>highlight.js</code> 的 <code>highlightAuto</code> 作为高亮函数</li></ul><h3 id="_3-对话标题自动生成" tabindex="-1">3. 对话标题自动生成 <a class="header-anchor" href="#_3-对话标题自动生成" aria-label="Permalink to &quot;3. 对话标题自动生成&quot;">​</a></h3><ul><li><code>useAiStore.ts</code> 的 <code>addUserMessage</code> <strong>已经实现</strong>：第一条用户消息自动截取前 40 字作为标题</li><li>无需改动 store，仅需侧边栏正确展示即可</li></ul><h3 id="_4-交互细节" tabindex="-1">4. 交互细节 <a class="header-anchor" href="#_4-交互细节" aria-label="Permalink to &quot;4. 交互细节&quot;">​</a></h3><ul><li><strong>代码块复制按钮</strong>：点击后图标变为 ✓，2 秒后复原</li><li><strong>消息复制按钮</strong>：hover AI 消息时右上角出现复制图标，复制纯文本内容</li><li><strong>时间戳</strong>：每条消息 hover 时显示发送时间（HH:mm 格式）</li><li><strong>顶部标题栏</strong>：<code>ChatWindow</code> 顶部固定栏，显示当前对话标题（无对话时隐藏）</li></ul><h3 id="_5-空状态欢迎页重构" tabindex="-1">5. 空状态欢迎页重构 <a class="header-anchor" href="#_5-空状态欢迎页重构" aria-label="Permalink to &quot;5. 空状态欢迎页重构&quot;">​</a></h3><ul><li>推荐问题改为列表布局（原为 2×2 grid）</li><li>按分类分组展示：&quot;常见问题&quot;、&quot;网络管理&quot;各 2 条</li><li>每条带 icon + 完整问题文本，点击直接发送</li></ul><hr><h2 id="受影响的文件" tabindex="-1">受影响的文件 <a class="header-anchor" href="#受影响的文件" aria-label="Permalink to &quot;受影响的文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>改动类型</th></tr></thead><tbody><tr><td><code>fronted/src/components/ai/MessageBubble.vue</code></td><td>重写布局 + 替换 renderMarkdown + 加复制/时间戳</td></tr><tr><td><code>fronted/src/components/ai/ChatWindow.vue</code></td><td>加顶部标题栏</td></tr><tr><td><code>fronted/src/components/ai/ChatInput.vue</code></td><td>修复 nextTick 导入 bug</td></tr><tr><td><code>fronted/src/components/ai/SuggestedPrompts.vue</code></td><td>重构为分组列表布局</td></tr><tr><td><code>fronted/src/stores/useAiStore.ts</code></td><td>无需改动（标题逻辑已存在）</td></tr><tr><td><code>fronted/package.json</code></td><td>新增 <code>marked</code>、<code>highlight.js</code> 依赖</td></tr></tbody></table><hr><h2 id="不在本次范围内" tabindex="-1">不在本次范围内 <a class="header-anchor" href="#不在本次范围内" aria-label="Permalink to &quot;不在本次范围内&quot;">​</a></h2><ul><li>侧边栏折叠功能</li><li>对话重命名</li><li>消息编辑/重新生成</li><li>后端 AI 生成标题</li></ul>',25)])])}const g=t(i,[["render",d]]);export{m as __pageData,g as default};
